import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Transaction } from '../../shared/Transictions/Transaction';
import { TransactionService } from '../../services/transaction.service';
import { AuthService } from '../../services/auth.service';
import { TransactionComponent } from '../transation/transaction';

@Component({
  selector: 'app-transaction-list',
  standalone: true,
  imports: [CommonModule, TransactionComponent],
  templateUrl: './transaction-list.component.html',
  styleUrls: ['./transaction-list.component.css']
})
export class TransactionListComponent implements OnInit {
  transactions: Transaction[] = [];
  isLoading = false;
  errorMessage = '';

  constructor(private auth: AuthService, private transactionsService: TransactionService) {}

  ngOnInit(): void {
    this.load();
  }

  load(): void {
    this.isLoading = true;
    this.errorMessage = '';
    this.transactionsService.fetch().subscribe({
      next: (data) => {
        this.transactions = data || [];
        this.isLoading = false;
      },
      error: (err) => {
        this.errorMessage = 'Falha ao carregar transações.';
        console.error('Transaction load error', err);
        this.isLoading = false;
      }
    });
  }
}
